import{_ as t,o as a,c as i,a3 as o}from"./chunks/framework.C6m_RRf-.js";const k=JSON.parse('{"title":"版本更新","description":"","frontmatter":{},"headers":[],"relativePath":"update.md","filePath":"update.md","lastUpdated":1790664780000}'),s={name:"update.md"};function l(n,e,c,p,d,r){return a(),i("div",null,[...e[0]||(e[0]=[o(`<h1 id="版本更新" tabindex="-1">版本更新 <a class="header-anchor" href="#版本更新" aria-label="Permalink to &quot;版本更新&quot;">​</a></h1><p>不同部署方式的更新方式也不同，请对号入座。更新部署成功后，请不要忘记同时更新前端的 Twikoo CDN 地址中的 <code>x.x.x</code> 数字版本号，使之与云函数版本号相同，然后部署网站。</p><h2 id="针对腾讯云-cloudbase-部署的更新方式" tabindex="-1">针对腾讯云 CloudBase 部署的更新方式 <a class="header-anchor" href="#针对腾讯云-cloudbase-部署的更新方式" aria-label="Permalink to &quot;针对腾讯云 CloudBase 部署的更新方式&quot;">​</a></h2><p>登录<a href="https://console.cloud.tencent.com/tcb/scf/index" target="_blank" rel="noreferrer">环境 - 云函数</a>，点击 twikoo，点击函数代码，打开 <code>package.json</code> 文件，确认依赖写的是 <code>&quot;twikoo-func&quot;: &quot;latest&quot;</code>（1.x 时代这里写的是固定版本号，建议一并改成 <code>latest</code>，以后升级就不用再改），点击“保存并安装依赖”即可。</p><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果您的云函数是 1.0.0 之前的版本，因为 1.0.0 版本修改了部署步骤，请先参考<a href="#手动部署">手动部署</a>，从第 5 步开始，重新创建云函数，再按照此步骤更新。</p><p>如果升级后出现无法读取评论列表，云函数报错，请在函数编辑页面，删除 <code>node_modules</code> 目录（删除需要半分钟左右，请耐心等待删除完成），再点击保存并安装依赖。如果仍然不能解决，请删除并重新创建 Twikoo 云函数。</p></div><div class="warning custom-block"><p class="custom-block-title">运行时版本</p><p>CloudBase 请将云函数运行时升级到 <strong>Node 20 及以上（推荐 24）</strong>；2.0 产物语法目标为 ES2022，不再兼容 Node 16.13。</p></div><h2 id="针对-vercel-部署的更新方式" tabindex="-1">针对 Vercel 部署的更新方式 <a class="header-anchor" href="#针对-vercel-部署的更新方式" aria-label="Permalink to &quot;针对 Vercel 部署的更新方式&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">不需要改版本号</p><p>一键部署的依赖写的是 <code>twikoo-vercel@latest</code>（见 <a href="https://github.com/twikoojs/twikoo/blob/main/templates/vercel-min/package.json" target="_blank" rel="noreferrer"><code>templates/vercel-min/package.json</code></a>）， 重新部署即可拿到最新稳定版。</p><p>注意 Vercel 默认复用构建缓存，缓存命中时不会重新解析 <code>latest</code>—— <strong>重新部署时取消勾选「Use existing Build Cache」</strong>，否则依赖还是旧的。</p></div><ol><li>进入 <a href="https://vercel.com/dashboard" target="_blank" rel="noreferrer">Vercel 仪表板</a> - twikoo - Deployments</li><li>在最新一次部署右侧点击更多（三个点）- Redeploy</li><li>在弹窗中取消勾选 Use existing Build Cache，点击 Redeploy</li><li>部署完成后访问域名，如果环境配置正确，可以看到“Twikoo 云函数运行正常”的提示</li></ol><h2 id="针对-railway-部署的更新方式" tabindex="-1">针对 Railway 部署的更新方式 <a class="header-anchor" href="#针对-railway-部署的更新方式" aria-label="Permalink to &quot;针对 Railway 部署的更新方式&quot;">​</a></h2><p>模板仓库 <a href="https://github.com/twikoojs/twikoo-zeabur" target="_blank" rel="noreferrer"><code>twikoojs/twikoo-zeabur</code></a> 的依赖写的是 <code>tkserver@latest</code>，<strong>不需要改版本号</strong>。</p><ol><li>登录 Github，找到部署时 fork 到自己账号下的名为 twikoo-zeabur 的仓库，点击 Sync fork 同步上游</li><li>部署会自动触发；如果没有触发、或更新后版本没变，到 Railway 控制台手动重新部署一次</li></ol><div class="tip custom-block"><p class="custom-block-title">如果你的 fork 里写的是固定版本号</p><p>把 <code>package.json</code> 里的 <code>&quot;tkserver&quot;: &quot;x.x.x&quot;</code> 改成 <code>&quot;tkserver&quot;: &quot;latest&quot;</code>，以后就只需要同步 fork 再重新部署。</p></div><h2 id="针对-netlify-部署的更新方式" tabindex="-1">针对 Netlify 部署的更新方式 <a class="header-anchor" href="#针对-netlify-部署的更新方式" aria-label="Permalink to &quot;针对 Netlify 部署的更新方式&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">Netlify Modern Functions 不兼容升级</p><p>新版 Netlify 部署模板将函数入口从旧的 CommonJS <code>exports.handler</code> 切换到 Modern Netlify Functions 的 ESM 默认入口，以便通过 <code>context.waitUntil()</code> 异步执行 <code>POST_SUBMIT</code>，避免邮件等后置通知阻塞评论提交。</p><p>这次升级同时涉及 <strong>npm 依赖、函数入口和 Node.js 版本</strong>，旧部署不能只修改其中一项：</p><ul><li>只升级 <code>twikoo-netlify</code>、仍保留旧 <code>require(...).handler</code>：可以继续运行，但仍走同步兼容路径，评论提交最多可能继续等待约 5 秒。</li><li>只同步新版模板、但仍安装旧版 <code>twikoo-netlify</code>：可能因缺少 Modern 默认入口而在构建或函数加载阶段失败。</li><li>仍使用 Node 18/20：新版 Modern 入口依赖要求 Node.js <strong>&gt;= 22.12.0</strong>。</li><li>旧 fork 同步上游时，<code>twikoo.js</code> 删除并改为 <code>twikoo.mjs</code> 可能产生冲突；遇到冲突时按下面步骤手工调整即可。</li></ul></div><p>如果你的 Netlify 部署来自旧模板，请按以下步骤完成一次不兼容升级：</p><ol><li><p>登录 GitHub，打开部署时 fork 的 <code>twikoo-netlify</code> 仓库，先点击 <strong>Sync fork</strong>。如果同步产生冲突，可以跳过自动合并，按后续步骤手工修改。</p></li><li><p>删除旧入口：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netlify/functions/twikoo.js</span></span></code></pre></div><p>新建：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>netlify/functions/twikoo.mjs</span></span></code></pre></div><p>内容为：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">default</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;twikoo-netlify&quot;</span></span></code></pre></div></li><li><p>确认 <code>package.json</code> 至少包含：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;dependencies&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;twikoo-netlify&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;latest&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  },</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;engines&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&gt;=22.12.0&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><p>在仓库根目录新建或更新 <code>.node-version</code>：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>24</span></span></code></pre></div><p>如果你在 Netlify 项目中另外配置过 <code>NODE_VERSION</code>，也请确保版本不低于 22.12.0，建议统一使用 24。</p></li><li><p>提交并推送以上修改。</p></li><li><p>回到 Netlify 控制台，进入 <strong>Deploys → Trigger deploy → Clear cache and deploy site</strong>。必须清理缓存，确保 <code>latest</code> 被重新解析并安装。</p></li><li><p>部署完成后访问云函数地址，确认能看到“Twikoo 云函数运行正常”的提示。</p></li><li><p>再提交一条测试评论，确认评论可以快速返回，同时邮件 / 即时消息通知仍能正常收到。</p></li></ol><div class="tip custom-block"><p class="custom-block-title">以后再升级</p><p>完成这次入口迁移后，后续正常升级只需要同步 <code>twikoo-netlify</code> 模板并重新部署即可。 如果依赖仍写为 <code>&quot;twikoo-netlify&quot;: &quot;latest&quot;</code>，无需手工修改版本号。</p></div><h2 id="针对-hugging-face-部署的更新方式" tabindex="-1">针对 Hugging Face 部署的更新方式 <a class="header-anchor" href="#针对-hugging-face-部署的更新方式" aria-label="Permalink to &quot;针对 Hugging Face 部署的更新方式&quot;">​</a></h2><blockquote><p>适用于所有 Docker Space。2026 年 7 月之后免费账号已无法创建新的 Space，详见<a href="./backend.html#hugging-face-部署">部署章节的前提说明</a>。</p></blockquote><ol><li>登录 Hugging Face，找到部署的 Space，点击上方 Settings，往下滚动找到并点击 Factory rebuild</li></ol><h2 id="针对私有部署的更新方式" tabindex="-1">针对私有部署的更新方式 <a class="header-anchor" href="#针对私有部署的更新方式" aria-label="Permalink to &quot;针对私有部署的更新方式&quot;">​</a></h2><ol><li>停止旧版本 <code>kill $(ps -ef | grep tkserver | grep -v &#39;grep&#39; | awk &#39;{print $2}&#39;)</code></li><li>拉取新版本 <code>npm i -g tkserver@latest</code></li><li>启动新版本 <code>nohup tkserver &gt;&gt; tkserver.log 2&gt;&amp;1 &amp;</code></li></ol><h2 id="针对私有部署-docker-的更新方式" tabindex="-1">针对私有部署 (Docker) 的更新方式 <a class="header-anchor" href="#针对私有部署-docker-的更新方式" aria-label="Permalink to &quot;针对私有部署 (Docker) 的更新方式&quot;">​</a></h2><ol><li>拉取新版本 <code>docker pull imaegoo/twikoo</code></li><li>停止旧版本容器 <code>docker stop twikoo</code></li><li>删除旧版本容器 <code>docker rm twikoo</code></li><li><a href="#私有部署-docker">启动新版本容器</a></li></ol><h2 id="自动更新" tabindex="-1">自动更新 <a class="header-anchor" href="#自动更新" aria-label="Permalink to &quot;自动更新&quot;">​</a></h2><p>考虑到可用性和安全性问题，Twikoo 没有实现自动更新，也没有计划实现自动更新。如果您希望实现自动更新，可以参考 MHuiG 基于 Github 工作流的 <a href="https://github.com/MHuiG/twikoo-update" target="_blank" rel="noreferrer">twikoo-update</a> 的实现方式。</p>`,27)])])}const u=t(s,[["render",l]]);export{k as __pageData,u as default};
